{code:swift}convenience init(
    error: NSError,
    customTitle: String? = nil,
    paymentsFilter: PaymentMethodsListFilter,
    completion: ((_ paymentMethod: PaymentMethodV2?) -> Void)?
) {
    let subtitle: String
    if let extraData = error.userInfo["extra_data"] as? NSDictionary,
       let data = extraData["error_data"] as? [String: Any],
       let text = data["text"] as? String {
        subtitle = text
    } else {
        subtitle = PaymentMethodsBottomSheetCreateModel.localizedError(with: error)
    }
    self.init(
        title: customTitle ?? PaymentMethodsBottomSheetCreateModel.localizedTitle(for: error),
        subtitle: subtitle,
        paymentsFilter: paymentsFilter,
        completion: completion
    )
}{code}

